import re
from datetime import date
from decimal import Decimal, InvalidOperation, localcontext

CENT = Decimal("0.01")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _prec_for(value: Decimal) -> int:
    tup = value.as_tuple()
    try:
        adj = value.adjusted()
    except Exception:
        adj = 0
    # Enough precision to represent value quantized to exponent -2.
    # Accounts for both significant digits and magnitude of exponent.
    need = len(tup.digits) + abs(tup.exponent) + 10 if isinstance(tup.exponent, int) else 30
    need = max(need, adj + 10)
    return max(28, need)


def _quantize_cents(value: Decimal, name: str) -> Decimal:
    try:
        with localcontext() as ctx:
            ctx.prec = _prec_for(value)
            q = value.quantize(CENT)
    except InvalidOperation:
        raise ValueError(f"invalid {name}: {value!r}") from None
    # Normalize -0.00 to 0.00
    if q == 0:
        q = Decimal("0.00")
    return q


def _money(value, name, allow_zero_amount=True):
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string")
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid {name}: {value!r}") from None
    if not amount.is_finite():
        raise ValueError(f"{name} must be finite")
    # Reject more than 2 decimal places based on representation:
    # exponent less than -2 means more than 2 digits after the point,
    # even if they are trailing zeros (e.g. "1.2300", "10.000", "0.000").
    if amount.as_tuple().exponent < -2:
        raise ValueError(f"{name} must have at most 2 decimal places")
    quantized = _quantize_cents(amount, name)
    return quantized


def _date(value, name):
    if not isinstance(value, str) or _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{name} must be YYYY-MM-DD")
    try:
        date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError(f"invalid {name}: {value!r}") from None
    return value


def _add_cents(a: Decimal, b: Decimal) -> Decimal:
    # Compute a + b exactly and quantize to 2 dp under sufficient precision
    # so large balances do not hit the default 28-digit context limit.
    prec = max(_prec_for(a), _prec_for(b))
    # Sum may need one extra digit / larger adjusted exponent.
    prec = max(prec, len(a.as_tuple().digits) + len(b.as_tuple().digits) + 10)
    try:
        with localcontext() as ctx:
            ctx.prec = prec
            s = a + b
            # Recompute precision for the sum's magnitude before quantize.
            ctx.prec = max(prec, _prec_for(s))
            q = s.quantize(CENT)
    except InvalidOperation:
        raise ValueError("balance out of range") from None
    if q == 0:
        q = Decimal("0.00")
    return q


def running_balance(transactions: list[dict], opening_balance: str) -> list[dict]:
    opening = _money(opening_balance, "opening_balance")
    if not isinstance(transactions, list):
        raise ValueError("transactions must be a list")
    seen = set()
    normalized = []
    for tx in transactions:
        if not isinstance(tx, dict):
            raise ValueError("each transaction must be a dict")
        for key in ("id", "value_date", "booking_date", "amount"):
            if key not in tx:
                raise ValueError(f"missing key: {key}")
        tx_id = tx["id"]
        if not isinstance(tx_id, str) or tx_id == "":
            raise ValueError("id must be a non-empty string")
        if tx_id in seen:
            raise ValueError(f"duplicate id: {tx_id!r}")
        seen.add(tx_id)
        value_date = _date(tx["value_date"], "value_date")
        booking_date = _date(tx["booking_date"], "booking_date")
        amount = _money(tx["amount"], "amount")
        normalized.append({"id": tx_id, "value_date": value_date, "booking_date": booking_date, "amount": amount})
    normalized.sort(key=lambda r: (r["value_date"], r["booking_date"], r["id"]))
    rows = []
    balance = opening
    for r in normalized:
        balance = _add_cents(balance, r["amount"])
        rows.append({"id": r["id"], "value_date": r["value_date"], "booking_date": r["booking_date"], "amount": r["amount"], "balance": balance})
    return rows


def closing_balance(transactions: list[dict], opening_balance: str) -> Decimal:
    rows = running_balance(transactions, opening_balance)
    if not rows:
        return _money(opening_balance, "opening_balance")
    return rows[-1]["balance"]
